fn trunc_len(n: usize, m: usize) -> usize {
    if m == 0 {
        n
    } else if m >= n {
        1
    } else {
        n - m
    }
}

fn legder(c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    let n = c.len();
    let out_len = trunc_len(n, m as usize);
    c.into_iter().take(out_len).collect()
}

